<?php require dirname(__DIR__).'/includes/bootstrap.php';admin_required();$id=(int)($_GET['id']??0);$guest=['name'=>'','relation'=>'','phone'=>'','email'=>'','personal_message'=>'','rsvp_status'=>'pending','is_active'=>1];if($id){$s=$pdo->prepare('SELECT * FROM guests WHERE id=?');$s->execute([$id]);$guest=$s->fetch()?:$guest;} $error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if(!$name)$error='Guest name is required.';elseif($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';else{$values=[$name,trim($_POST['relation']??''),trim($_POST['phone']??''),$email,trim($_POST['personal_message']??''),in_array($_POST['rsvp_status']??'', ['pending','attending','maybe','declined'],true)?$_POST['rsvp_status']:'pending',isset($_POST['is_active'])?1:0];if($id){$values[]=$id;$pdo->prepare('UPDATE guests SET name=?,relation=?,phone=?,email=?,personal_message=?,rsvp_status=?,is_active=? WHERE id=?')->execute($values);flash('success','Guest updated successfully.');}else{$slug=slugify($name);$pdo->prepare('INSERT INTO guests(name,relation,phone,email,personal_message,rsvp_status,is_active,slug) VALUES(?,?,?,?,?,?,?,?)')->execute([...$values,$slug]);$id=(int)$pdo->lastInsertId();flash('success','Invitation created successfully.');}redirect('admin/guest-form.php?id='.$id);}}$pageTitle=$id?'Edit Guest':'Add Guest';require '_header.php';if($id){$s=$pdo->prepare('SELECT * FROM guests WHERE id=?');$s->execute([$id]);$guest=$s->fetch();$url=base_url('invite/'.$guest['slug']);}?><section class="page-head"><div><h1><?=e($pageTitle)?></h1><p>Personal details are shown only where appropriate.</p></div><a class="btn" href="guests.php">← Guests</a></section><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($id):?><section class="link-card"><div><span>Invitation link for <?=e($guest['name'])?></span><b><?=e($url)?></b></div><button class="btn copy-link" data-copy="<?=e($url)?>">Copy Link</button><a class="btn" target="_blank" href="<?=e($url)?>">Open Invitation</a><a class="btn whatsapp" target="_blank" href="https://wa.me/?text=<?=rawurlencode('Hi '.$guest['name'].', you are warmly invited to our wedding celebration. Please find your personalized invitation here: '.$url)?>">Share</a></section><?php endif;?><form method="post" class="panel form-grid wide"><?=csrf_field()?><div class="split"><label>Guest Name *<input name="name" required value="<?=e($guest['name'])?>"></label><label>Family / Relation<input name="relation" value="<?=e($guest['relation'])?>" placeholder="e.g. Family friend"></label></div><div class="split"><label>Phone Number<input name="phone" value="<?=e($guest['phone'])?>"></label><label>Email<input name="email" type="email" value="<?=e($guest['email'])?>"></label></div><label>Personal Message<textarea name="personal_message" rows="4" placeholder="An optional message shown in the invitation"><?=e($guest['personal_message'])?></textarea></label><div class="split"><label>RSVP Status<select name="rsvp_status"><?php foreach(['pending','attending','maybe','declined'] as $s):?><option <?=$guest['rsvp_status']===$s?'selected':''?> value="<?=$s?>"><?=ucfirst($s)?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="is_active" <?=$guest['is_active']?'checked':''?>> Invitation active</label></div><button class="btn primary">Save Guest</button></form><?php require '_footer.php';?>

